(sh) => {
    sh.uniforms.uTime = U.uTime; sh.uniforms.uBeat = U.uBeat; sh.uniforms.uBreath = U.uBreath;
    sh.uniforms.uVein = { value: veinC }; sh.uniforms.uPulse = { value: pulse }; sh.uniforms.uSway = { value: sway }; sh.uniforms.uWet = { value: wet };
    if (rimC) sh.uniforms.uRim = { value: rimC };
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', '#include <common>\nattribute vec3 aFlesh;\nuniform float uTime, uBeat, uBreath, uPulse, uSway;\nvarying vec3 vFlesh;\nvarying vec3 vFlPos;')
      .replace('#include <begin_vertex>', `#include <begin_vertex>
        vFlesh = aFlesh; vFlPos = position;
        ${sway ? 'transformed.x += sin(uTime * 1.1 + position.y * 0.55 + position.z * 0.3) * aFlesh.y * uSway; transformed.z += cos(uTime * 0.83 + position.y * 0.4 + position.x * 0.5) * aFlesh.y * uSway;'
    : 'transformed += normal * aFlesh.y * uPulse * (uBeat + 0.35 * sin(uTime * 1.3 + position.y * 0.7 + position.x * 0.4) + 0.4 * uBreath);'}`);
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', '#include <common>\nuniform float uTime, uBeat, uWet;\nuniform vec3 uVein;\n' + (rimC ? 'uniform vec3 uRim;\n' : '') + 'varying vec3 vFlesh;\nvarying vec3 vFlPos;\n' + NOISE_GLSL + BUMP_GLSL)
      .replace('#include <specularmap_fragment>', `#include <specularmap_fragment>
        float flPore = flN(vFlPos * 11.0);
        specularStrength *= mix(0.3, 1.0 + uWet, vFlesh.z) * (0.75 + 0.5 * flPore);
        diffuseColor.rgb *= 0.86 + 0.22 * flN(vFlPos * 3.1 + 7.0);
        // capillary web: thin ridged-noise lines, darker and purplish like veins under skin
        float flC1 = abs(flN(vFlPos * 2.4 + vec3(3.1, 0.0, 5.7)) - 0.5), flCap = 1.0 - smoothstep(0.0, min(0.03, fwidth(flC1) * 1.6), flC1);
        float flC2 = abs(flN(vFlPos * 4.1 + 11.0) - 0.5), flCap2 = 1.0 - smoothstep(0.0, min(0.022, fwidth(flC2) * 1.3), flC2);
        float flFar = smoothstep(0.02, 0.08, length(fwidth(vFlPos))); flCap *= flFar; flCap2 *= flFar;   // a far-field detail only: up close it would read as contour lines
        diffuseColor.rgb = mix(diffuseColor.rgb, diffuseColor.rgb * vec3(0.5, 0.22, 0.34), flCap * 0.3 + flCap2 * 0.12);
        float flGlint = flN(vFlPos * 23.0 + uTime * 0.15);
        specularStrength *= 1.0 + 1.4 * smoothstep(0.72, 0.95, flGlint) * vFlesh.z;`)
      .replace('#include <normal_fragment_maps>', `#include <normal_fragment_maps>
        // wrinkles + pores + raised capillaries as a procedural bump
        float flH0 = flN(vFlPos * 1.6) * 0.6 + flN(vFlPos * 4.7 + 2.0) * 0.18 - flPore * 0.05 + flCap * 0.12 + flCap2 * 0.04;
        normal = flBump(-vViewPosition, normal, flH0, 0.22);`)
      .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
        totalEmissiveRadiance += uVein * vFlesh.x * (0.18 + 1.5 * uBeat) + uVein * flCap * 0.012 * (0.4 + uBeat);
        // subsurface-style back-scatter: grazing angles glow deep red, as if light passes through the meat
        float flSSS = pow(1.0 - abs(dot(normalize(vViewPosition), normal)), 3.0);
        totalEmissiveRadiance += vec3(0.3, 0.015, 0.025) * flSSS * (0.4 + 0.3 * uBeat) * diffuseColor.r * 0.7;
        ${rimC ? 'float flRim = pow(1.0 - abs(dot(normalize(vViewPosition), normal)), 2.2); totalEmissiveRadiance += uRim * flRim * (0.45 + 0.8 * uBeat); diffuseColor.a *= mix(0.45, 1.0, flRim);' : ''}`);
  }

